B.ZE=s(["Move to higher ground immediately. Do not wait for the water to reach you.","Never walk or drive through flood water: 15 cm can knock you down, 30 cm can float a car.","Turn off electricity at the main switch if it is safe to reach.","Stay away from fallen power lines and fast-moving water."],t.s)
B.T_=s(["\u0e22\u0e49\u0e32\u0e22\u0e44\u0e1b\u0e17\u0e35\u0e48\u0e2a\u0e39\u0e07\u0e17\u0e31\u0e19\u0e17\u0e35 \u0e2d\u0e22\u0e48\u0e32\u0e23\u0e2d\u0e43\u0e2b\u0e49\u0e19\u0e49\u0e33\u0e21\u0e32\u0e16\u0e36\u0e07\u0e15\u0e31\u0e27","\u0e2d\u0e22\u0e48\u0e32\u0e40\u0e14\u0e34\u0e19\u0e2b\u0e23\u0e37\u0e2d\u0e02\u0e31\u0e1a\u0e23\u0e16\u0e25\u0e38\u0e22\u0e19\u0e49\u0e33\u0e17\u0e48\u0e27\u0e21: \u0e19\u0e49\u0e33\u0e2a\u0e39\u0e07 15 \u0e0b\u0e21. \u0e01\u0e47\u0e17\u0e33\u0e43\u0e2b\u0e49\u0e25\u0e49\u0e21\u0e44\u0e14\u0e49 \u0e41\u0e25\u0e30 30 \u0e0b\u0e21. \u0e01\u0e47\u0e1e\u0e31\u0e14\u0e23\u0e16\u0e25\u0e2d\u0e22\u0e44\u0e14\u0e49","\u0e16\u0e49\u0e32\u0e40\u0e02\u0e49\u0e32\u0e16\u0e36\u0e07\u0e44\u0e14\u0e49\u0e2d\u0e22\u0e48\u0e32\u0e07\u0e1b\u0e25\u0e2d\u0e14\u0e20\u0e31\u0e22 \u0e43\u0e2b\u0e49\u0e15\u0e31\u0e14\u0e44\u0e1f\u0e17\u0e35\u0e48\u0e40\u0e1a\u0e23\u0e01\u0e40\u0e01\u0e2d\u0e23\u0e4c\u0e2b\u0e25\u0e31\u0e01","\u0e2d\u0e22\u0e39\u0e48\u0e2b\u0e48\u0e32\u0e07\u0e08\u0e32\u0e01\u0e2a\u0e32\u0e22\u0e44\u0e1f\u0e17\u0e35\u0e48\u0e02\u0e32\u0e14\u0e41\u0e25\u0e30\u0e01\u0e23\u0e30\u0e41\u0e2a\u0e19\u0e49\u0e33\u0e40\u0e0a\u0e35\u0e48\u0e22\u0e27"],t.s)
B.QF=new A.ft("During a flood","\u0e23\u0e30\u0e2b\u0e27\u0e48\u0e32\u0e07\u0e19\u0e49\u0e33\u0e17\u0e48\u0e27\u0e21",B.nx,B.fZ,B.ZE,B.T_)
B.QS=new A.aZ(57820,"MaterialIcons",!1)
B.a2j=s(["Leave early, before roads are covered.","Take your go-bag, phone, charger and any medicines.","Lock the door, switch off gas and electricity.","Help children, elderly and disabled neighbours.","Tell someone where you are going and use the SOS button if you are stuck."],t.s)
B.a_6=s(["\u0e2d\u0e2d\u0e01\u0e08\u0e32\u0e01\u0e1a\u0e49\u0e32\u0e19\u0e41\u0e15\u0e48\u0e40\u0e19\u0e34\u0e48\u0e19 \u0e46 \u0e01\u0e48\u0e2d\u0e19\u0e17\u0e35\u0e48\u0e16\u0e19\u0e19\u0e08\u0e30\u0e16\u0e39\u0e01\u0e19\u0e49\u0e33\u0e17\u0e48\u0e27\u0e21","\u0e2b\u0e22\u0e34\u0e1a\u0e16\u0e38\u0e07\u0e22\u0e31\u0e07\u0e0a\u0e35\u0e1e \u0e42\u0e17\u0e23\u0e28\u0e31\u0e1e\u0e17\u0e4c \u0e17\u0e35\u0e48\u0e0a\u0e32\u0e23\u0e4c\u0e08 \u0e41\u0e25\u0e30\u0e22\u0e32\u0e17\u0e35\u0e48\u0e15\u0e49\u0e2d\u0e07\u0e43\u0e0a\u0e49","\u0e25\u0e47\u0e2d\u0e01\u0e1b\u0e23\u0e30\u0e15\u0e39 \u0e1b\u0e34\u0e14\u0e41\u0e01\u0e4a\u0e2a\u0e41\u0e25\u0e30\u0e44\u0e1f\u0e1f\u0e49\u0e32","\u0e0a\u0e48\u0e27\u0e22\u0e40\u0e14\u0e47\u0e01 \u0e1c\u0e39\u0e49\u0e2a\u0e39\u0e07\u0e2d\u0e32\u0e22\u0e38 \u0e41\u0e25\u0e30\u0e1c\u0e39\u0e49\u0e1e\u0e34\u0e01\u0e32\u0e23\u0e43\u0e19\u0e25\u0e30\u0e41\u0e27\u0e01\u0e1a\u0e49\u0e32\u0e19","\u0e1a\u0e2d\u0e01\u0e04\u0e19\u0e2d\u0e37\u0e48\u0e19\u0e27\u0e48\u0e32\u0e04\u0e38\u0e13\u0e08\u0e30\u0e44\u0e1b\u0e17\u0e35\u0e48\u0e44\u0e2b\u0e19 \u0e41\u0e25\u0e30\u0e01\u0e14\u0e1b\u0e38\u0e48\u0e21 SOS \u0e04\u0e49\u0e32\u0e07\u0e44\u0e27\u0e49\u0e2b\u0e32\u0e01\u0e15\u0e34\u0e14\u0e2d\u0e22\u0e39\u0e48"],t.s)
B.QG=new A.ft("Evacuation checklist","\u0e23\u0e32\u0e22\u0e01\u0e32\u0e23\u0e40\u0e15\u0e23\u0e35\u0e22\u0e21\u0e2d\u0e1e\u0e22\u0e1e",B.QS,B.fZ,B.a2j,B.a_6)
